import {db,ui,persist,rerender,navigate,esc,money,num,pct,icon,formatDate,teamAccounts,teamTypes,teamUsers,filteredAccounts,aggregate,badgeStatus,modal,closeModal,toast,timeLabel,isValidDate} from './core.js';

import {isCountryCode,countryLabel} from './countries.js';
import {renderGeoPicker,bindGeoPicker} from './geo-picker.js';
import {renderIssueDatePicker,bindIssueDatePicker} from './date-picker.js';
import {getCampaignCount,renderCampaignCount,bindCampaignTooltips,renderAccountHelp,getDisabledReason} from './account-tooltips.js';
import {csvNumber,downloadCsv} from './csv.js';

const PAGE_SIZE=12;
const drafts={};
let extended=false;
const byId=(id)=>teamAccounts().find(a=>a.id===id);
const typeOf=(id)=>teamTypes(true).find(t=>t.id===id);
const buyerOf=(id)=>teamUsers().find(u=>u.id===id);
const canManage=()=>db.role==='admin'||db.role==='lead';
const displayNet=a=>aggregate([a]).net;
const displayRoi=a=>aggregate([a]).roi;
const cls=n=>n==null?'muted':n<0?'negative':'positive';
const options=(items,value,label)=>items.map(x=>`<option value="${esc(x.id)}" ${x.id===value?'selected':''}>${esc(label?label(x):x.name)}</option>`).join('');
const metaDate='23 октября 2026';
export function buildAccountsExport(rows=sortRows(filteredAccounts())){
 const headers=['ID кабинета Facebook','Название кабинета','Тип кабинета','Байер','Дата выдачи','GEO','Стоимость кабинета, USD','Кампании, шт.','Spend, USD','Revenue, USD','Profit до стоимости кабинета, USD','Profit с учётом стоимости кабинета, USD','ROI, %','Raw Spend, USD','Разница Spend − Raw Spend, USD','Статус','Причина Disabled','Данные по дату'];
 return {filename:'accounts.csv',headers,rows:rows.map(a=>{
  const g=aggregate([a]);
  return [String(a.id),a.name,typeOf(a.typeId)?.name||'',buyerOf(a.buyerId)?.username||'',a.date,a.geo||'',csvNumber(g.cost),getCampaignCount(a),csvNumber(g.spend),csvNumber(g.revenue),csvNumber(g.profit),csvNumber(g.net),csvNumber(g.roi),csvNumber(g.raw),csvNumber(g.spend==null||g.raw==null?null:g.spend-g.raw),a.status||'Нет статуса',a.status==='Disabled'?getDisabledReason(a):'','2026-10-23'];
 })};
}
function sortRows(rows){return [...rows].sort((a,b)=>{let av,bv;const k=ui.accountSort;av=k==='net'?displayNet(a):k==='roi'?displayRoi(a):k==='typeId'?typeOf(a.typeId)?.name:k==='buyerId'?buyerOf(a.buyerId)?.username:k==='campaigns'?getCampaignCount(a):a[k];bv=k==='net'?displayNet(b):k==='roi'?displayRoi(b):k==='typeId'?typeOf(b.typeId)?.name:k==='buyerId'?buyerOf(b.buyerId)?.username:k==='campaigns'?getCampaignCount(b):b[k];if(av==null)return bv==null?0:1;if(bv==null)return -1;return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv),'ru'))*ui.sortDir;});}
function sortHead(label,key,extra=''){return `<th ${extra}><div class="account-column-heading"><button type="button" class="sort-btn ${ui.accountSort===key?'sorted':''}" data-sort="${key}" data-account-help="${key}" aria-label="Сортировать: ${esc(label)}">${label}${ui.accountSort===key?`<span aria-hidden="true">${ui.sortDir>0?'↑':'↓'}</span>`:'<span class="sort-idle" aria-hidden="true">↕</span>'}</button>${renderAccountHelp(key,label)}</div></th>`;}
function plainHead(label,key){return `<th><div class="account-column-heading"><button type="button" class="account-header-label" data-account-help="${key}" aria-label="Описание: ${esc(label)}">${label}</button>${renderAccountHelp(key,label)}</div></th>`;}
function metricLabel(label,key){return `<span class="account-metric-label"><span>${label}</span>${renderAccountHelp(key,label)}</span>`;}
function accountStatus(a){return a.status==='Disabled'?`<button type="button" class="account-status-help" data-account-disabled="${esc(a.id)}" aria-label="Disabled. ${esc(getDisabledReason(a))}" aria-expanded="false">${badgeStatus(a.status)}</button>`:badgeStatus(a.status);}
const signedMoney=value=>`${value>0?'+':''}${money(value,2)}`;
function selectedVisible(rows){return rows.filter(a=>ui.selected.has(a.id));}
function campaignBadge(a){return a.campaigns?.length?'':`<span class="badge badge-amber account-campaign-badge" title="У этого кабинета нет связанных кампаний AIO.">Нет кампаний</span>`;}
const totalFields={spend:['spend'],revenue:['revenue'],net:['profit','cost'],roi:['profit','spend','cost'],raw:['raw'],diff:['spend','raw'],cost:['cost']};
const totalFieldLabels={spend:'Spend',revenue:'Revenue AIO',profit:'Profit AIO',raw:'Raw Spend Meta',cost:'Стоимость кабинетов'};
export function accountTotals(rows){const g=aggregate(rows);return {...g,campaignCount:rows.reduce((n,a)=>n+getCampaignCount(a),0),diff:g.spend==null||g.raw==null?null:g.spend-g.raw};}
function totalValue(g,key){
 const missing=(totalFields[key]||[]).filter(f=>g.missingCounts?.[f]>0),parts=[];
 for(const f of missing)parts.push(`${totalFieldLabels[f]} получен для ${num(g.knownCounts[f])} из ${num(g.count)} кабинетов.`);
 if(missing.length)parts.push(g[key]==null?'Показатель пока недоступен. Отсутствие данных не означает нулевой результат.':'Предварительный показатель рассчитан по доступным данным. Отсутствующие значения не считаются подтверждёнными нулями.');
 if(key==='net')parts.push('Profit AIO − известная фактическая стоимость всех кабинетов выборки, включая кабинеты без финансовых данных.');
 else if(key==='roi'){parts.push('(Суммарный Profit AIO − стоимость кабинетов) / (суммарный Spend + стоимость) × 100%. Проценты кабинетов не усредняются. Известная стоимость всех кабинетов выборки учитывается, включая кабинеты без финансовых данных.');if(g.roi==null&&!missing.length&&g.count)parts.push('Не рассчитывается при нулевом или отрицательном знаменателе.');}
 else if(key==='diff')parts.push('Суммарный Spend − суммарный Raw Spend Meta. Плюс означает, что Spend больше Raw Spend; минус — что Raw Spend больше Spend.');
 else parts.push('Сумма по всем кабинетам, соответствующим фильтрам, независимо от страницы и выделения.');
 const formatted=key==='roi'?pct(g[key]):`${key==='diff'&&g[key]>0?'+':''}${money(g[key],2)}`;
 return `<button type="button" class="account-total-value ${missing.length?'account-total-partial':''}" data-account-value-tooltip="${esc(parts.join(' '))}" aria-label="${esc(formatted+'. '+parts.join(' '))}">${formatted}${missing.length?'<sup class="account-partial-mark" aria-hidden="true">*</sup>':''}</button>`;
}
function desktopTotals(g){return `<tfoot><tr class="account-totals-row"><td class="check-cell"></td><th scope="row"><strong>Итого</strong><small>${num(g.count)} кабинетов</small></th><td class="muted account-total-scope">По всей выборке</td><td class="num-cell" title="Общее число связанных кампаний в выбранных кабинетах">${num(g.campaignCount)}</td><td class="num-cell">${totalValue(g,'spend')}</td><td class="num-cell">${totalValue(g,'revenue')}</td><td class="num-cell ${cls(g.net)}">${totalValue(g,'net')}</td><td class="num-cell ${cls(g.roi)}">${totalValue(g,'roi')}</td>${extended?`<td class="num-cell">${totalValue(g,'raw')}</td><td class="num-cell">${totalValue(g,'diff')}</td><td class="num-cell">${totalValue(g,'cost')}</td><td></td>`:''}<td></td>${extended?'<td></td>':''}<td></td></tr></tfoot>`;}
function mobileTotals(g){return `<section class="account-mobile-totals" aria-label="Итого по всей выборке"><div class="row-between"><strong>Итого по всей выборке</strong><span class="muted">${num(g.count)} каб. · ${num(g.campaignCount)} камп.</span></div><dl class="account-total-grid">${[['spend','Spend'],['revenue','Revenue'],['net','Profit с учётом кабинетов'],['roi','ROI'],...(extended?[['raw','Raw Spend Meta'],['diff','Разница Spend'],['cost','Стоимость кабинетов']]:[])].map(([key,label])=>`<div><dt>${label}</dt><dd class="${['net','roi'].includes(key)?cls(g[key]):''}">${totalValue(g,key)}</dd></div>`).join('')}</dl></section>`;}
function filters(){const f=ui.filters;return `<div class="account-filters"><label class="search-box">${icon('search')}<input id="account-search" type="search" placeholder="Найти кабинет по названию или ID" value="${esc(f.search)}" aria-label="Поиск кабинетов"></label><div class="account-filter-selects"><label><span class="sr-only">Байер</span><select id="accounts-buyer" aria-label="Фильтр по байеру"><option value="all">Все байеры</option>${options(teamUsers(),f.buyer,u=>u.username)}</select></label><label><span class="sr-only">Тип</span><select id="accounts-type" aria-label="Фильтр по типу"><option value="all">Все типы</option>${options(teamTypes(true),f.type)}</select></label><label><span class="sr-only">Статус</span><select id="accounts-status" aria-label="Фильтр по статусу">${[['all','Все статусы'],['Active','Active'],['Disabled','Disabled'],['Unsettled','Unsettled'],['unknown','Нет статуса']].map(([v,l])=>`<option value="${v}" ${f.status===v?'selected':''}>${l}</option>`).join('')}</select></label>${renderIssueDatePicker('accounts-period','compact')}<label><span class="sr-only">GEO</span><select id="accounts-geo" aria-label="Фильтр GEO"><option value="all">Все GEO</option>${[...new Set(teamAccounts().map(a=>a.geo).filter(Boolean))].sort().map(g=>`<option ${f.geo===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><button class="btn btn-ghost btn-sm" id="accounts-reset" title="Сбросить фильтры">Сбросить</button></div>${f.completeness==='missing'?`<div class="account-filter-chips"><button class="badge badge-amber account-filter-chip" id="accounts-clear-completeness" aria-label="Снять фильтр без финансовых данных">Без финансовых данных ${icon('close')}</button></div>`:''}</div>`;}
export function renderAccounts(){
 const rows=sortRows(filteredAccounts()),total=rows.length;ui.accountPage=Math.max(1,Math.min(ui.accountPage||1,Math.ceil(total/PAGE_SIZE)||1));
 const page=rows.slice((ui.accountPage-1)*PAGE_SIZE,ui.accountPage*PAGE_SIZE);const countSelected=selectedVisible(rows).length;const totals=accountTotals(rows);
 return `<div class="page-header"><div><div class="eyebrow">РЕЕСТР КАБИНЕТОВ</div><h1>Кабинеты <span class="heading-count">${num(teamAccounts().length)}</span></h1><p class="muted">Каждый кабинет, его стоимость и результат — в одном месте.</p></div><div class="inline account-heading-actions"><button type="button" class="btn" id="accounts-export" ${total?'':'disabled'} title="Все кабинеты по текущим фильтрам, со всех страниц. При импорте в Excel задайте столбцу ID тип «Текст».">${icon('download')}Выгрузить CSV</button><button class="btn btn-primary" data-add="single">${icon('plus')}Добавить кабинеты</button></div></div>
 <section class="panel account-panel"><div class="account-toolbar"><div class="inline"><h2>Все кабинеты</h2><span class="badge">${total}</span></div><div class="inline"><button class="btn btn-ghost btn-sm ${extended?'active':''}" id="accounts-extended">${icon('grid')}${extended?'Основные колонки':'Показать сверку'}</button><button class="btn btn-ghost btn-sm" data-add="bulk">${icon('plus')}Добавить списком</button></div></div>${filters()}
 ${countSelected?`<div class="account-selection"><span>Выбрано: <b>${countSelected}</b></span>${canManage()?`<button class="btn btn-sm" id="accounts-reassign-selected">${icon('users')}Переназначить</button>`:''}<button class="btn btn-ghost btn-sm" id="accounts-clear-selection">Снять выбор</button></div>`:''}
 <div class="table-wrap account-table-desktop"><table class="data-table account-table"><thead><tr><th class="check-cell"><input type="checkbox" id="accounts-select-page" aria-label="Выбрать кабинеты на странице" ${page.length&&page.every(a=>ui.selected.has(a.id))?'checked':''}>${renderAccountHelp('select','Выбор кабинетов')}</th>${sortHead('Кабинет','name')}${sortHead('Тип / байер','typeId')}${sortHead('Кампании','campaigns')}${sortHead('Spend','spend')}${sortHead('Revenue','revenue')}${sortHead('Profit','net')}${sortHead('ROI','roi')}${extended?sortHead('Raw Spend','raw')+plainHead('Разница','diff')+sortHead('Цена каб.','cost')+sortHead('Выдан','date'):''}${sortHead('Статус','status')}${extended?plainHead('Причина Disabled','reason'):''}<th class="account-open-heading">${renderAccountHelp('open','Карточка кабинета')}</th></tr></thead><tbody>${page.map(a=>{const t=typeOf(a.typeId),b=buyerOf(a.buyerId),diff=a.spend==null||a.raw==null?null:a.spend-a.raw;return `<tr data-account="${esc(a.id)}" tabindex="0" aria-label="Открыть кабинет ${esc(a.name)}"><td class="check-cell"><input class="select-account" data-id="${esc(a.id)}" type="checkbox" ${ui.selected.has(a.id)?'checked':''} aria-label="Выбрать ${esc(a.name)}"></td><td><div class="account-identity"><span class="account-symbol">${icon('accounts')}</span><div><div class="account-name-line"><strong>${esc(a.name)}</strong>${campaignBadge(a)}</div><span class="mono id-text">${esc(a.id)}</span></div></div></td><td><div class="type-label"><span class="type-dot" style="background:${esc(t?.color||'#999')}"></span>${esc(t?.name||'—')}</div><span class="muted cell-secondary">${esc(b?.username||'—')}</span></td><td class="num-cell account-campaign-cell">${renderCampaignCount(a)}</td><td class="num-cell">${money(a.spend,2)}</td><td class="num-cell">${money(a.revenue,2)}</td><td class="num-cell ${cls(displayNet(a))}">${money(displayNet(a),2)}</td><td class="num-cell ${cls(displayRoi(a))}">${pct(displayRoi(a))}</td>${extended?`<td class="num-cell">${money(a.raw,2)}</td><td class="num-cell ${diff!=null&&Math.abs(diff)>Math.max(5,(a.raw||0)*.05)?'warning-text':''}">${signedMoney(diff)}</td><td class="num-cell">${money(a.cost,2)}</td><td class="date-cell">${formatDate(a.date)}</td>`:''}<td>${accountStatus(a)}</td>${extended?`<td class="account-disabled-reason-cell">${a.status==='Disabled'?esc(getDisabledReason(a)):'—'}</td>`:''}<td>${icon('chevron')}</td></tr>`;}).join('')||`<tr><td colspan="${extended?15:10}"><div class="empty">${icon('search')}<h3>Кабинеты не найдены</h3><p>Попробуйте изменить фильтры или добавить новый кабинет.</p><button class="btn" id="accounts-empty-reset">Сбросить фильтры</button></div></td></tr>`}</tbody>${desktopTotals(totals)}</table></div>
 <div class="account-mobile-list">${page.map(a=>`<article class="account-mobile-card"><div class="row-between"><label class="inline"><input type="checkbox" class="select-account" data-id="${esc(a.id)}" ${ui.selected.has(a.id)?'checked':''} aria-label="Выбрать ${esc(a.name)}"><strong>${esc(a.name)}</strong></label>${accountStatus(a)}</div>${a.status==='Disabled'?`<div class="account-mobile-disabled-reason"><span>Причина Disabled</span><p>${esc(getDisabledReason(a))}</p></div>`:''}<div class="account-mobile-campaigns"><span>Кампании</span>${renderCampaignCount(a)}</div><button class="account-mobile-open" data-open-account="${esc(a.id)}"><span class="mono id-text">${esc(a.id)}</span>${campaignBadge(a)}<span class="muted">${esc(typeOf(a.typeId)?.name)} · ${esc(buyerOf(a.buyerId)?.username)}</span><span class="mobile-metrics"><span>Spend<b>${money(a.spend)}</b></span><span>Profit<b class="${cls(displayNet(a))}">${money(displayNet(a))}</b></span><span>ROI<b class="${cls(displayRoi(a))}">${pct(displayRoi(a))}</b></span></span><span class="mobile-detail-link">Подробнее ${icon('chevron')}</span></button></article>`).join('')||'<div class="empty"><h3>Кабинеты не найдены</h3><p>Измените фильтры выше.</p></div>'}${mobileTotals(totals)}</div>
 <div class="account-table-footer"><span class="muted">${total?`${(ui.accountPage-1)*PAGE_SIZE+1}–${Math.min(ui.accountPage*PAGE_SIZE,total)}`:'0'} из ${num(total)} кабинетов</span><div class="inline"><span class="muted">Страница ${ui.accountPage} из ${Math.max(1,Math.ceil(total/PAGE_SIZE))}</span><button class="btn btn-sm" id="accounts-prev" ${ui.accountPage<=1?'disabled':''} aria-label="Предыдущая страница">←</button><button class="btn btn-sm" id="accounts-next" ${ui.accountPage>=Math.ceil(total/PAGE_SIZE)?'disabled':''} aria-label="Следующая страница">→</button></div></div></section>
`;
}
export function bindAccounts(){
 document.getElementById('accounts-export')?.addEventListener('click',()=>{
  const report=buildAccountsExport();if(!report.rows.length)return;
  downloadCsv(report.filename,report.headers,report.rows);toast(`CSV выгружен: ${report.rows.length} кабинетов`);
 });
 bindIssueDatePicker('accounts-period');
 bindCampaignTooltips(byId);
 const changeFilter=(key,val)=>{ui.filters[key]=val;ui.accountPage=1;ui.selected.clear();rerender();};
 document.getElementById('account-search')?.addEventListener('input',e=>{const val=e.target.value,position=e.target.selectionStart;changeFilter('search',val);const field=document.getElementById('account-search');field?.focus();try{field?.setSelectionRange(position,position);}catch{}});
 ['buyer','type','status','geo'].forEach(k=>document.getElementById('accounts-'+k)?.addEventListener('change',e=>changeFilter(k,e.target.value)));
 document.querySelectorAll('[data-sort]').forEach(e=>e.onclick=()=>{ui.sortDir=ui.accountSort===e.dataset.sort?-ui.sortDir:1;ui.accountSort=e.dataset.sort;rerender();});
 const reset=()=>{ui.filters={buyer:'all',type:'all',status:'all',period:'month',dateFrom:'',dateTo:'',geo:'all',search:'',completeness:'all'};ui.accountPage=1;ui.selected.clear();rerender();};
 ['accounts-reset','accounts-empty-reset'].forEach(id=>{const b=document.getElementById(id);if(b)b.onclick=reset;});
 document.querySelectorAll('[data-account]').forEach(e=>{e.onclick=ev=>{if(ev.target.closest('input,button,a'))return;openAccount(e.dataset.account);};e.onkeydown=ev=>{if(ev.key==='Enter'&&ev.target===e)openAccount(e.dataset.account);};});
 document.querySelectorAll('[data-open-account]').forEach(e=>e.onclick=()=>openAccount(e.dataset.openAccount));
 document.querySelectorAll('.select-account').forEach(e=>e.onchange=()=>{e.checked?ui.selected.add(e.dataset.id):ui.selected.delete(e.dataset.id);rerender();});
 const all=document.getElementById('accounts-select-page');if(all)all.onchange=()=>{sortRows(filteredAccounts()).slice((ui.accountPage-1)*PAGE_SIZE,ui.accountPage*PAGE_SIZE).forEach(a=>all.checked?ui.selected.add(a.id):ui.selected.delete(a.id));rerender();};
 document.getElementById('accounts-clear-selection')?.addEventListener('click',()=>{ui.selected.clear();rerender();});
 document.getElementById('accounts-reassign-selected')?.addEventListener('click',()=>openReassign(selectedVisible(filteredAccounts()).map(a=>a.id)));
 document.getElementById('accounts-extended')?.addEventListener('click',()=>{extended=!extended;rerender();});
 document.getElementById('accounts-prev')?.addEventListener('click',()=>{ui.accountPage--;rerender();});
 document.getElementById('accounts-next')?.addEventListener('click',()=>{ui.accountPage++;rerender();});
 document.getElementById('accounts-clear-completeness')?.addEventListener('click',()=>changeFilter('completeness','all'));
}
export function renderCampaignDetails(campaigns=[]){return Array.isArray(campaigns)&&campaigns.length?`<div class="detail-campaigns">${campaigns.map(c=>`<article class="detail-campaign"><div class="campaign-heading"><span class="campaign-id mono" aria-label="ID кампании AIO">${esc(c.id)}</span><strong>${esc(c.name)}</strong></div><dl class="campaign-finances"><div><dt>Spend</dt><dd>${money(c.spend,2)}</dd></div><div><dt>Revenue</dt><dd>${money(c.revenue,2)}</dd></div><div><dt>Profit AIO</dt><dd class="${cls(c.profit)}">${money(c.profit,2)}</dd></div></dl></article>`).join('')}</div>`:'<p class="muted">У этого кабинета пока нет связанных кампаний AIO.</p>';}
export function openAccount(id){
 const a=byId(id);if(!a){toast('Кабинет недоступен в этой команде');return;}
 const diff=a.raw==null||a.spend==null?null:a.spend-a.raw;const dp=a.raw&&diff!=null?diff/a.raw*100:null;
 modal(a.name,`<div class="account-detail-title"><span class="mono">${esc(a.id)}</span><button class="btn btn-ghost btn-sm" id="detail-copy" aria-label="Копировать ID">${icon('copy')}Копировать ID</button>${accountStatus(a)}</div>
 <div class="detail-financial-grid"><div>${metricLabel('Spend','spend')}<strong>${money(a.spend,2)}</strong></div><div>${metricLabel('Revenue','revenue')}<strong>${money(a.revenue,2)}</strong></div><div>${metricLabel('Profit с учётом кабинета','net')}<strong class="${cls(displayNet(a))}">${money(displayNet(a),2)}</strong></div><div>${metricLabel('ROI с учётом кабинета','roi')}<strong class="${cls(displayRoi(a))}">${pct(displayRoi(a))}</strong></div></div>
 ${a.spend==null?'<div class="notice">Финансовые данные ещё не получены. Нулевые Revenue и Profit не подставляются.</div>':''}
 <div class="detail-section"><h3>Данные кабинета</h3><dl class="detail-pairs"><div><dt>Тип</dt><dd>${esc(typeOf(a.typeId)?.name||'—')}</dd></div><div><dt>Байер</dt><dd>${esc(buyerOf(a.buyerId)?.username||'—')}</dd></div><div><dt>Дата выдачи</dt><dd>${formatDate(a.date)}</dd></div><div><dt>Фактическая стоимость</dt><dd>${money(a.cost,2)}</dd></div><div><dt>GEO</dt><dd>${esc(countryLabel(a.geo)||'Не указан')}</dd></div><div><dt>Причина Disabled</dt><dd>${a.status==='Disabled'?esc(getDisabledReason(a)):'—'}</dd></div></dl></div>
 <div class="detail-section"><div class="row-between"><h3>Сверка источников</h3></div><dl class="detail-pairs"><div><dt>${metricLabel('Raw Spend · Meta','raw')}</dt><dd>${money(a.raw,2)}</dd></div><div><dt>${metricLabel('Spend · Roll Up','spend')}</dt><dd>${money(a.spend,2)}</dd></div><div><dt>${metricLabel('Разница','diff')}</dt><dd>${signedMoney(diff)} <span class="muted">${dp==null?'':`(${pct(dp)})`}</span></dd></div><div><dt>Profit AIO до стоимости кабинета</dt><dd>${money(a.profit,2)}</dd></div></dl><p class="muted small">Raw Spend показан для сверки и повторно не вычитается из прибыли. Данные с ${formatDate(a.date)} по ${metaDate}.</p></div>
 <div class="detail-section"><div class="row-between"><h3>Связанные кампании</h3><span class="badge">${a.campaigns?.length||0}</span></div>${renderCampaignDetails(a.campaigns)}</div>
 <div class="detail-source-times"><span>Meta: ${timeLabel(db.sync.meta.lastSuccess)}</span><span>Roll Up: ${timeLabel(db.sync.rollup.lastSuccess)}</span></div>`,`${canManage()?`<button class="btn" id="detail-reassign">${icon('users')}Переназначить</button><button class="btn" id="detail-edit">${icon('edit')}Исправить запись</button>`:''}<button class="btn btn-primary" id="detail-done">Закрыть</button>`,true);
 bindCampaignTooltips(byId);
 document.getElementById('detail-done').onclick=closeModal;
 document.getElementById('detail-copy').onclick=()=>copyText(a.id);
 document.getElementById('detail-reassign')?.addEventListener('click',()=>openReassign([a.id]));
 document.getElementById('detail-edit')?.addEventListener('click',()=>openEdit(a.id));
}
function copyText(value){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(value).then(()=>toast('Скопировано')).catch(()=>toast('Выделите и скопируйте ID вручную'));else toast('Выделите и скопируйте ID вручную');}
function openEdit(id){const a=byId(id);if(!a||!canManage())return;modal('Исправить запись',`<form id="edit-account-form"><div class="form-grid"><label class="field">Название<input name="name" value="${esc(a.name)}" required maxlength="80"></label><label class="field">Тип кабинета<select name="typeId">${options(teamTypes(true),a.typeId,t=>t.name+(t.archived?' · в архиве':''))}</select></label><label class="field">Фактическая стоимость, USD<input name="cost" type="number" value="${a.cost}" min="0" step="0.01" required></label><label class="field">Дата выдачи<input name="date" type="date" value="${a.date}" max="2026-10-23" required></label>${renderGeoPicker('edit-geo',a.geo||'')}</div><div class="notice">Изменение стоимости пересчитает результат этого кабинета. Текущая цена типа не меняется.</div><label class="field">Причина исправления<input name="reason" placeholder="Например, уточнена цена покупки" required maxlength="160"></label><p class="form-error" id="edit-error" role="alert"></p></form>`,`<button class="btn" id="edit-cancel">Отмена</button><button class="btn btn-primary" type="submit" form="edit-account-form">Сохранить изменения</button>`);bindGeoPicker('edit-geo');document.getElementById('edit-cancel').onclick=()=>openAccount(id);document.getElementById('edit-account-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const cost=Number(f.get('cost'));const date=f.get('date');if(!Number.isFinite(cost)||cost<0||!isValidDate(date)||date>'2026-10-23'||!f.get('reason').trim()||(f.get('geo')&&!isCountryCode(f.get('geo')))){document.getElementById('edit-error').textContent='Проверьте стоимость, дату и причину исправления.';return;}const before={cost:a.cost,date:a.date,typeId:a.typeId};Object.assign(a,{name:f.get('name').trim(),typeId:f.get('typeId'),cost,date,geo:f.get('geo')||''});a.changes=[...(a.changes||[]),{at:Date.now(),by:db.currentUserId,before,reason:f.get('reason').trim()}];persist();rerender();openAccount(id);toast('Запись исправлена');};}
function openReassign(ids){if(!canManage())return;const rows=ids.map(byId).filter(Boolean);if(!rows.length)return;modal(rows.length>1?'Переназначить кабинеты':'Переназначить кабинет',`<p>${rows.length>1?`Выбрано ${rows.length} кабинетов.`:`Кабинет <b>${esc(rows[0].name)}</b> сейчас у ${esc(buyerOf(rows[0].buyerId)?.username)}.`}</p><label class="field">Новый байер<select id="reassign-user">${options(teamUsers().filter(u=>u.status==='active'),rows[0].buyerId,u=>u.username)}</select></label><div class="notice notice-amber">Вся статистика и стоимость ${rows.length>1?'кабинетов':'кабинета'} будут учитываться у нового байера, включая прошлые периоды. Даты выдачи и стоимость сохранятся.</div>`,`<button class="btn" id="reassign-cancel">Отмена</button><button class="btn btn-primary" id="reassign-save">Переназначить</button>`);document.getElementById('reassign-cancel').onclick=()=>rows.length===1?openAccount(rows[0].id):closeModal();document.getElementById('reassign-save').onclick=()=>{const target=document.getElementById('reassign-user').value;if(!teamUsers().some(u=>u.id===target&&u.status==='active'))return;rows.forEach(a=>{a.changes=[...(a.changes||[]),{at:Date.now(),by:db.currentUserId,from:a.buyerId,to:target,reason:'Переназначение вместе со всей историей'}];a.buyerId=target;});persist();ui.selected.clear();rerender();closeModal();toast(`Переназначено: ${rows.length}. Вся история сохранена.`);};}
function getDraft(mode){
 let d=drafts[db.teamId];
 if(!d){const t=teamTypes()[0];d=drafts[db.teamId]={mode:mode||'single',ids:'',singleId:'',buyerId:db.currentUserId,typeId:t?.id||'',cost:t?.price??0,date:'2026-10-23',geo:'',geoQuery:'',rowOverrides:[]};}
 if(mode&&mode!==d.mode){if(mode==='single'&&!d.singleId)d.singleId=d.ids.split(/[\n,;\s]+/)[0]||'';if(mode==='bulk'&&!d.ids)d.ids=d.singleId;d.mode=mode;}
 if(db.role==='buyer')d.buyerId=db.currentUserId;
 return d;
}
function captureDraft(){const d=getDraft(),field=id=>document.getElementById(id);if(field('add-ids')){if(d.mode==='single')d.singleId=field('add-ids').value;else d.ids=field('add-ids').value;}if(field('add-buyer'))d.buyerId=field('add-buyer').value;if(field('add-type'))d.typeId=field('add-type').value;if(field('add-cost'))d.cost=field('add-cost').value;if(field('add-date'))d.date=field('add-date').value;if(field('add-geo'))d.geo=field('add-geo').value;if(field('add-geo-search'))d.geoQuery=field('add-geo-search').value;return d;}
export function openAdd(mode='single'){
 const d=getDraft(mode);
 modal('Добавить кабинеты',`<div class="tabs add-tabs"><button class="tab ${d.mode==='single'?'active':''}" id="add-single">Один кабинет</button><button class="tab ${d.mode==='bulk'?'active':''}" id="add-bulk">Списком</button></div><form id="add-form"><label class="field">${d.mode==='bulk'?'ID кабинетов Facebook, по одному на строку':'ID кабинета Facebook'}${d.mode==='bulk'?`<textarea id="add-ids" rows="5" placeholder="239450000000000&#10;239450000023319" required>${esc(d.ids)}</textarea>`:`<input id="add-ids" value="${esc(d.singleId)}" placeholder="Например, 239450000000000" inputmode="numeric" autocomplete="off" required>`}</label><div class="form-grid"><label class="field">Байер<select id="add-buyer" ${db.role==='buyer'?'disabled':''}>${options(teamUsers().filter(u=>u.status==='active'),d.buyerId,u=>u.username)}</select></label><label class="field"><span class="row-between">Тип кабинета<button type="button" class="text-button" id="add-new-type">+ Новый тип</button></span><select id="add-type" required>${teamTypes().length?options(teamTypes(),d.typeId):'<option value="">Сначала создайте тип</option>'}</select></label><label class="field">Цена за один кабинет, USD<input id="add-cost" type="number" min="0" step="0.01" value="${esc(d.cost)}" required><span class="field-hint">${d.mode==='bulk'?'Применяется к каждому кабинету в списке. Цена типа не меняется.':'Используется в расчётах этого кабинета. Цена типа не меняется.'}</span></label><label class="field">Дата выдачи<input id="add-date" type="date" max="2026-10-23" value="${esc(d.date)}" required><span class="field-hint" id="add-past-hint">${d.date<'2026-10-23'?'Проверьте стоимость на дату получения.':'Можно указать прошлую дату.'}</span></label>${renderGeoPicker('add-geo',d.geo,d.geoQuery)}</div><p class="form-error" id="add-error" role="alert"></p><div class="notice">${icon('info')}Добавляется запись кабинета. Статус и финансовые показатели будут доступны после подключения синхронизации.</div></form>`,`<button class="btn" id="add-cancel">Отмена</button><button class="btn btn-primary" form="add-form" type="submit">${d.mode==='bulk'?'Проверить список':'Добавить кабинет'}</button>`,true);
 bindGeoPicker('add-geo',(code,text)=>{d.geo=code;d.geoQuery=text;});
 document.getElementById('add-form').addEventListener('input',captureDraft);
 document.getElementById('add-form').addEventListener('change',captureDraft);
 document.getElementById('add-cancel').onclick=()=>{captureDraft();closeModal();};
 ['single','bulk'].forEach(m=>document.getElementById('add-'+m).onclick=()=>{captureDraft();openAdd(m);});
 document.getElementById('add-type').onchange=e=>{document.getElementById('add-cost').value=typeOf(e.target.value)?.price??0;};
 document.getElementById('add-date').onchange=e=>{document.getElementById('add-past-hint').textContent=e.target.value<'2026-10-23'?'Проверьте стоимость на дату получения.':'Можно указать прошлую дату.';};
 document.getElementById('add-new-type').onclick=()=>{captureDraft();quickType();};
 document.getElementById('add-form').onsubmit=e=>{
  e.preventDefault();captureDraft();const errors=validateCommon(d);if(errors){document.getElementById('add-error').textContent=errors;return;}
  const ids=(d.mode==='single'?d.singleId:d.ids).trim().split(/[\n\r,;\s]+/).filter(Boolean);
  if(!ids.length){document.getElementById('add-error').textContent='Укажите хотя бы один ID кабинета.';return;}
  if(d.mode==='single'&&ids.length>1){document.getElementById('add-error').textContent='Для нескольких ID выберите режим «Списком».';return;}
  const rows=validateRows(ids,d,d.mode==='bulk'?d.rowOverrides:[]);
  if(d.mode==='single'){if(rows[0].error){document.getElementById('add-error').textContent=rows[0].error;return;}saveRows(rows,d);return;}
  showBulkPreview(rows,d);
 };
}
function validateCommon(d){if(!teamTypes().some(t=>t.id===d.typeId))return 'Выберите действующий тип кабинета.';if(!teamUsers().some(u=>u.id===d.buyerId&&u.status==='active'))return 'Выберите активного байера своей команды.';if(db.role==='buyer'&&d.buyerId!==db.currentUserId)return 'Байер может добавлять кабинеты только себе.';if(d.cost===''||!Number.isFinite(Number(d.cost))||Number(d.cost)<0)return 'Стоимость должна быть числом не меньше нуля.';if(!isValidDate(d.date)||d.date>'2026-10-23')return 'Укажите сегодняшнюю или прошлую дату выдачи.';if(d.geo&&!isCountryCode(d.geo))return 'Выберите GEO из списка стран.';if(d.geoQuery&&d.geoQuery!==countryLabel(d.geo))return 'Выберите GEO из списка стран или очистите поле.';return '';}
function validateRows(ids,d,overrides=[]){const seen=new Set();return ids.map((id,i)=>{id=id.trim();const over=(overrides[i]?.id===id||!overrides[i]?.id?overrides[i]:overrides.find(r=>r.id===id))||{},typeId=over.typeId||d.typeId,cost=over.cost??d.cost;const found=(db.catalog||[]).find(a=>a.team===db.teamId&&a.id===id);let error='';if(!/^\d+$/.test(id))error='ID должен содержать только цифры';else if(seen.has(id))error='Повтор ID в этом списке';else if(teamAccounts().some(a=>a.id===id))error='Уже добавлен в реестр';else if(!teamTypes().some(t=>t.id===typeId))error='Выберите действующий тип';else if(cost===''||!Number.isFinite(Number(cost))||Number(cost)<0)error='Некорректная цена';seen.add(id);return {id,name:found?.name||'Кабинет '+id,typeId,cost:Number(cost),error};});}
function showBulkPreview(rows,d,success=''){
 const valid=rows.filter(r=>!r.error),total=valid.reduce((n,r)=>n+r.cost,0);modal('Проверка списка',`${success?`<div class="notice notice-green">${icon('check')}${esc(success)}</div>`:''}<div class="bulk-summary"><div><span>Готово к добавлению</span><strong>${valid.length} <small>из ${rows.length}</small></strong></div><div><span>Стоимость выбранных кабинетов</span><strong>${money(total,2)}</strong></div></div><p class="muted small">Байер: ${esc(buyerOf(d.buyerId)?.username)} · Выданы ${formatDate(d.date)}. Можно исправить ID, тип и цену каждой строки.</p><div class="bulk-preview-list">${rows.map((r,i)=>`<div class="bulk-preview-row ${r.error?'has-error':''}" data-row="${i}"><div class="bulk-row-main"><span class="bulk-index">${i+1}</span><div class="bulk-id-field"><label class="sr-only" for="bulk-id-${i}">ID строки ${i+1}</label><input id="bulk-id-${i}" class="bulk-id mono" value="${esc(r.id)}" inputmode="numeric"><span class="${r.error?'form-error':'muted'} small">${r.error?esc(r.error):`${esc(r.name)} · Готов к добавлению`}</span></div><span class="bulk-valid-icon ${r.error?'negative':'positive'}">${icon(r.error?'warning':'check')}</span></div><div class="bulk-row-options"><label class="field"><span>Тип</span><select class="bulk-type">${options(teamTypes(),r.typeId)}</select></label><label class="field"><span>Цена, USD</span><input class="bulk-cost" type="number" min="0" step="0.01" value="${r.cost}"></label></div></div>`).join('')}</div><div class="notice">Ошибочные строки не будут добавлены. После сохранения корректных кабинетов их можно исправить.</div>`,`<button class="btn" id="bulk-back">Назад</button><button class="btn" id="bulk-recheck">Перепроверить</button><button class="btn btn-primary" id="bulk-save" ${valid.length?'':'disabled'}>Добавить ${valid.length}</button>`,true);
 const collect=()=>{const nodes=[...document.querySelectorAll('.bulk-preview-row')];const ids=nodes.map(n=>n.querySelector('.bulk-id').value.trim());const overrides=nodes.map(n=>({typeId:n.querySelector('.bulk-type').value,cost:n.querySelector('.bulk-cost').value,id:n.querySelector('.bulk-id').value.trim()}));d.ids=ids.join('\n');d.rowOverrides=overrides;return validateRows(ids,d,overrides);};
 document.querySelectorAll('.bulk-type').forEach(s=>s.onchange=()=>{s.closest('.bulk-row-options').querySelector('.bulk-cost').value=typeOf(s.value)?.price??0;collect();document.getElementById('bulk-save').disabled=true;document.getElementById('bulk-save').textContent='Сначала перепроверьте';});
 document.querySelectorAll('.bulk-id,.bulk-cost').forEach(s=>s.oninput=()=>{collect();document.getElementById('bulk-save').disabled=true;document.getElementById('bulk-save').textContent='Сначала перепроверьте';});
 document.getElementById('bulk-back').onclick=()=>{collect();openAdd('bulk');};document.getElementById('bulk-recheck').onclick=()=>showBulkPreview(collect(),d,success);document.getElementById('bulk-save').onclick=()=>saveRows(collect(),d);
}
function saveRows(rows,d){const common=validateCommon(d);if(common){toast(common);return;}const valid=rows.filter(r=>!r.error&&!teamAccounts().some(a=>a.id===r.id));const invalid=rows.filter(r=>r.error);if(!valid.length)return;valid.forEach(r=>db.accounts.push({id:r.id,name:r.name,team:db.teamId,buyerId:d.buyerId,typeId:r.typeId,cost:r.cost,date:d.date,geo:d.geo||'',raw:null,spend:null,revenue:null,profit:null,status:null,reason:'',campaigns:[]}));persist();rerender();toast(`Добавлено кабинетов: ${valid.length}`);if(invalid.length){d.ids=invalid.map(r=>r.id).join('\n');d.rowOverrides=invalid.map(r=>({id:r.id,typeId:r.typeId,cost:r.cost}));const remaining=validateRows(invalid.map(r=>r.id),d,d.rowOverrides);showBulkPreview(remaining,d,`Добавлено ${valid.length}. Осталось исправить: ${remaining.length}.`);}else{delete drafts[db.teamId];closeModal();}}
function quickType(){const d=getDraft();modal('Новый тип кабинета',`<form id="quick-type-form"><label class="field">Название<input name="name" required maxlength="80" placeholder="Например, North · Verified"></label><label class="field">Цена по умолчанию, USD<input name="price" type="number" min="0" step="0.01" value="25" required></label><p class="form-error" id="quick-type-error"></p><p class="muted small">Тип будет доступен всем участникам вашей команды. Уже добавленные кабинеты сохранят свою стоимость.</p></form>`,`<button class="btn" id="quick-type-cancel">Назад</button><button class="btn btn-primary" form="quick-type-form" type="submit">Создать тип</button>`);document.getElementById('quick-type-cancel').onclick=()=>openAdd(d.mode);document.getElementById('quick-type-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),price=Number(f.get('price'));if(!name||!Number.isFinite(price)||price<0||teamTypes(true).some(t=>t.name.toLowerCase()===name.toLowerCase())){document.getElementById('quick-type-error').textContent='Проверьте название и цену. Названия типов не должны повторяться.';return;}const t={id:'t-'+Date.now(),name,price,team:db.teamId,color:'#6987c0',archived:false};db.types.push(t);d.typeId=t.id;d.cost=price;persist();rerender();openAdd(d.mode);toast('Тип создан');};}
